command:example.dev:code:
# Exportar y comparar con la copia de seguridad anterior
$current = Export-ColorScriptMetadata -Path "./current-metadata.json" -IncludeFileInfo -PassThru
$previous = Get-Content "./previous-metadata.json" | ConvertFrom-Json
$new = $current | Where-Object { $_.Name -notin $previous.Name }
$removed = $previous | Where-Object { $_.Name -notin $current.Name }
Write-Host "Scripts nuevos: $($new.Count) | Scripts eliminados: $($removed.Count)"

dev:remarks.maml:para:
Recupera el directorio de caché resuelto. `Cache.Path` sigue siendo la anulación opcional configurada por el usuario;
`Cache.EffectivePath` muestra el directorio que el módulo realmente usa después de los valores predeterminados de la plataforma y
Se aplican anulaciones de entorno.

command:example.dev:code:
$config = Get-ColorScriptConfiguration
if ($config.Startup.AutoShowOnImport) {
    Write-Host "Los scripts de inicio están habilitados"
}

$config = Get-ColorScriptConfiguration
if ($config.Cache.Path) {
    Write-Host "Ruta de caché personalizada configurada: $($config.Cache.Path)"
} else {
    Write-Host "Se usa la ruta de caché predeterminada"
}

Write-Host "Ruta de caché efectiva: $($config.Cache.EffectivePath)"

# Construir caché para scripts filtrado
Get-ColorScriptList -Tag Recommended -AsObject |
    ForEach-Object {
        New-ColorScriptCache -Name $_.Name -PassThru
    } |
    Format-Table Name, Status

# Encuentre el primer script que coincida con un patrón para una visualización rápida
$script = Get-ColorScriptList -Name "aurora-*" -AsObject | Select-Object -First 1
if ($script) {
    Show-ColorScript -Name $script.Name -PassThru
}

# Verifique que todos los scripts a los que se hace referencia existan antes de ejecutar la automatización
$requiredScripts = @("bars", "arch", "mandelbrot-zoom")
$available = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Name
$missing = $requiredScripts | Where-Object { $_ -notin $available }
if ($missing) {
    Write-Warning "Scripts que faltan: $($missing -join ', ')"
} else {
    Write-Host "Todos los scripts necesarios están disponibles"
}

# Crear múltiples scripts de colores para un proyecto
$scriptNames = @("company-logo", "team-banner", "status-display")
foreach ($name in $scriptNames) {
    New-ColorScript -Name $name -Category "Corporate" -Tag "Custom" -OutputPath ".\src" | Out-Null
}
Write-Host "Se crearon $($scriptNames.Count) plantillas de scripts de colores"

# Verificar las convenciones de nombres script
$validName = "123-start"
$invalidNames = @("-invalid", "_underscore-only", "contains space")
foreach ($name in $invalidNames) {
    try {
        New-ColorScript -Name $name -OutputPath ./temp -WhatIf -ErrorAction Stop
    } catch {
        Write-Warning "Nombre no válido '$name': $_"
    }
}

# Crear con validación de categoría y etiqueta.
$categories = Get-ColorScriptList -AsObject | Select-Object -ExpandProperty Category -Unique
if ("Retro" -in $categories) {
    New-ColorScript -Name "retro-party" -OutputPath ./ColorScripts-Enhanced/Scripts -Category "Artistic" -Tag "Fun","Social"
} else {
    Write-Warning "No se encontró la categoría Retro"
}

# Verificar que el reinicio fue exitoso
$config = Reset-ColorScriptConfiguration -PassThru
if ($null -eq $config.Cache.Path -and $config.Cache.EffectivePath) {
    Write-Host "La configuración se restableció al valor predeterminado de la plataforma"
} else {
    Write-Host "Configuración restablecida, pero se usa una ruta personalizada: $($config.Cache.Path)"
}

# Crea una presentación de diapositivas de scripts de colores geométrico
Get-ColorScriptList -Category Geometric -AsObject |
    ForEach-Object {
        Show-ColorScript -Name $_.Name
        Start-Sleep -Seconds 3
    }

# Ejemplo de manejo de errores
try {
    Show-ColorScript -Name "nonexistent-script" -ErrorAction Stop
} catch {
    Write-Warning "Script no encontrado: $_"
    Show-ColorScript  # Alternativa: mostrar una selección aleatoria
}

# Construir integración de automatización
if ($env:CI) {
    Show-ColorScript -Name "Galaxy" -NoCache
} else {
    Show-ColorScript  # Visualización aleatoria para uso interactivo
}

# Tarea programada para saludo de terminal
$scriptPath = "$(Get-Module ColorScripts-Enhanced).ModuleBase\Scripts\mandelbrot-zoom.ps1"
if (Test-Path $scriptPath) {
    & $scriptPath
} else {
    Show-ColorScript -Name mandelbrot-zoom
}
